$availableOffers=[];$offerStatement=$db->prepare("SELECT o.*,(SELECT COUNT(*) FROM offer_redemptions r JOIN bookings b ON b.id=r.booking_id WHERE r.offer_id=o.id AND b.status NOT IN ('cancelled','rejected')) usage_count,(SELECT COUNT(*) FROM offer_redemptions r JOIN bookings b ON b.id=r.booking_id WHERE r.offer_id=o.id AND r.user_email=? AND b.status NOT IN ('cancelled','rejected')) customer_usage FROM offers o JOIN offer_packages op ON op.offer_id=o.id WHERE op.package_id=? AND o.status='active' AND NOW() BETWEEN o.booking_start_at AND o.booking_end_at ORDER BY o.priority DESC,o.discount_value DESC");if($offerStatement){$offerStatement->bind_param('si',$email,$package['id']);$offerStatement->execute();$offerResult=$offerStatement->get_result();while($offer=$offerResult->fetch_assoc())$availableOffers[]=$offer;}
