<script>
document.addEventListener('DOMContentLoaded',()=>{
 const editBookingData=<?php echo json_encode($editFormData,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT);?>;
 const packageUnitPrice=<?php echo json_encode((float)$package['price']);?>,availableOffers=<?php echo json_encode($availableOffers,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT);?>;
 const from=document.querySelector('#from-date'),to=document.querySelector('#to-date'),durationDays=<?php echo max(1,(int)$package['duration_days']);?>,hotelSelect=document.querySelector('#hotel-select'),hotelUpgradeTotal=document.querySelector('#hotel-upgrade-total'),includeSelf=document.querySelector('#include-self'),familySection=document.querySelector('#family-travellers'),otherSection=document.querySelector('#other-traveller-list').closest('.traveller-section'),list=document.querySelector('#other-traveller-list'),template=document.querySelector('#traveller-template'),addButton=document.querySelector('#add-traveller'),people=document.querySelector('#people-count'),offerInput=document.querySelector('[name="offer_code"]'),offerPreview=document.querySelector('#offer-preview');
 const bookingForm=document.querySelector('#booking-form'),confirmModal=document.querySelector('#booking-confirm-modal'),confirmSummary=document.querySelector('#booking-confirm-summary'),confirmSubmit=document.querySelector('#confirm-booking-submit');let bookingConfirmed=false;
 const money=value=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(Number(value||0));
 const html=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));
 const ageFromDob=value=>{if(!value)return null;const birth=new Date(value+'T00:00:00'),today=new Date();if(Number.isNaN(birth.getTime())||birth>today)return null;let age=today.getFullYear()-birth.getFullYear();if(today.getMonth()<birth.getMonth()||(today.getMonth()===birth.getMonth()&&today.getDate()<birth.getDate()))age--;return age};
 const category=age=>age===null?'unknown':age<18?'child':age>=60?'senior':'adult';
 const priceRates={adult:1,child:.5,senior:.9,unknown:1};
 const priceLabel={adult:'Adults',child:'Children',senior:'Seniors',unknown:'Travellers'};
 const selectedPriceCounts=()=>{const counts={adult:0,child:0,senior:0,unknown:0};const add=value=>{const type=category(ageFromDob(value));counts[type]!==undefined?counts[type]++:counts.unknown++};if(includeSelf?.checked)add(includeSelf.dataset.dob);if(!familySection.hidden)document.querySelectorAll('input[name="family_ids[]"]:checked').forEach(input=>add(input.dataset.dob));if(!otherSection.hidden)list.querySelectorAll('.other-traveller-card').forEach(card=>add(card.querySelector('[name="other_dob[]"]').value));return counts};
 const offerBlockReason=(offer,packageBase,travellers)=>{if(Number(offer.usage_limit)>0&&Number(offer.usage_count)>=Number(offer.usage_limit))return'exhausted';if(Number(offer.per_customer_limit)>0&&Number(offer.customer_usage)>=Number(offer.per_customer_limit))return'already_used';if(travellers<Number(offer.minimum_travellers||0))return'min_travellers';if(packageBase<Number(offer.minimum_booking_amount||0))return'min_amount';return''};
 const offerDiscount=(offer,packageBase,travellers)=>{if(offerBlockReason(offer,packageBase,travellers))return 0;let discount=0,value=Number(offer.discount_value||0);if(offer.discount_type==='percentage')discount=packageBase*Math.min(100,value)/100;else discount=offer.calculation_scope==='per_traveller'?value*travellers:value;if(Number(offer.maximum_discount)>0)discount=Math.min(discount,Number(offer.maximum_discount));return Math.round(Math.min(packageBase,Math.max(0,discount))*100)/100};
 const bestOffer=(packageBase,travellers)=>{const code=offerInput.value.trim().toUpperCase();let best=null,codeMatch=false,blockedReason='';if(code){availableOffers.forEach(offer=>{if(String(offer.code||'').toUpperCase()!==code)return;codeMatch=true;const reason=offerBlockReason(offer,packageBase,travellers);if(reason){blockedReason=blockedReason||reason;return}const discount=offerDiscount(offer,packageBase,travellers);if(discount<=0)return;const candidate={offer,discount,source:'code'};if(!best||discount>best.discount||(discount===best.discount&&Number(offer.priority||0)>Number(best.offer.priority||0)))best=candidate});return best||{offer:null,discount:0,source:'code',codeStatus:codeMatch?(blockedReason||'not_eligible'):'invalid'}}availableOffers.forEach(offer=>{if(Number(offer.is_automatic)!==1)return;const discount=offerDiscount(offer,packageBase,travellers);if(discount<=0)return;const candidate={offer,discount,source:'automatic'};if(!best||discount>best.discount||(discount===best.discount&&Number(offer.priority||0)>Number(best.offer.priority||0)))best=candidate});return best};
 const amountDetails=()=>{const travellers=Number(people.value||0),hotelRate=Number(hotelSelect?.selectedOptions[0]?.dataset.surcharge||0),priceCounts=selectedPriceCounts();let packageBase=0;Object.keys(priceCounts).forEach(type=>{packageBase+=packageUnitPrice*priceRates[type]*priceCounts[type]});packageBase=Math.round(packageBase*100)/100;const hotelTotal=hotelRate*travellers,base=packageBase+hotelTotal,offer=bestOffer(packageBase,travellers),discount=offer&&offer.offer?offer.discount:0,total=Math.max(0,base-discount);return{travellers,hotelRate,priceCounts,packageBase,hotelTotal,offer,discount,total}};
 const packageRows=details=>Object.keys(details.priceCounts).filter(type=>details.priceCounts[type]>0).map(type=>'<div class="booking-confirm-row"><span><strong>'+priceLabel[type]+'</strong><small>'+money(packageUnitPrice*priceRates[type])+' x '+details.priceCounts[type]+' traveller'+(details.priceCounts[type]===1?'':'s')+(type==='child'?' · 50% child rate':(type==='senior'?' · 90% senior rate':''))+'</small></span><b>'+money(packageUnitPrice*priceRates[type]*details.priceCounts[type])+'</b></div>').join('');
 const offerMessage=details=>{const code=offerInput.value.trim().toUpperCase();if(details.offer?.offer){const offer=details.offer.offer,name=offer.name||offer.code||'Offer discount';return{type:'success',html:'<strong>'+html(name)+'</strong><small>'+html(offer.code?('Code '+offer.code+' applied'):'Automatic offer applied')+'</small>',amount:'-'+money(details.discount)}}if(code&&details.offer?.codeStatus==='invalid')return{type:'warning',html:'<strong>Coupon not found</strong><small>'+html(code)+' is not active for this package.</small>',amount:money(0)};if(code&&details.offer?.codeStatus==='already_used')return{type:'warning',html:'<strong>Coupon already used</strong><small>This offer is limited to one use per customer.</small>',amount:money(0)};if(code&&details.offer?.codeStatus==='exhausted')return{type:'warning',html:'<strong>Coupon limit reached</strong><small>This offer has reached its total usage limit.</small>',amount:money(0)};if(code&&details.offer?.codeStatus==='min_travellers')return{type:'warning',html:'<strong>Coupon requirements not met</strong><small>Add the minimum required travellers for this offer.</small>',amount:money(0)};if(code&&details.offer?.codeStatus==='min_amount')return{type:'warning',html:'<strong>Coupon requirements not met</strong><small>The package subtotal is below the minimum booking amount.</small>',amount:money(0)};if(code&&details.offer?.codeStatus==='not_eligible')return{type:'warning',html:'<strong>Coupon requirements not met</strong><small>Check minimum travellers, amount, or usage limit.</small>',amount:money(0)};return null};
 const offerPreviewText=message=>message.html.replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();
 const updateOfferPreview=()=>{if(!offerPreview)return;const details=amountDetails(),message=offerMessage(details);offerPreview.className='offer-preview';if(!message){offerPreview.textContent='';return}offerPreview.classList.add(message.type==='success'?'is-success':'is-warning');offerPreview.textContent=message.type==='success'?'Coupon discount: '+message.amount:'Coupon not applied: '+offerPreviewText(message)};
 const openConfirmModal=()=>{const details=amountDetails(),message=offerMessage(details);confirmSummary.innerHTML=packageRows(details)+(details.hotelTotal>0?'<div class="booking-confirm-row"><span><strong>Hotel upgrade</strong><small>'+money(details.hotelRate)+' x '+details.travellers+' traveller'+(details.travellers===1?'':'s')+'</small></span><b>'+money(details.hotelTotal)+'</b></div>':'<div class="booking-confirm-row"><span><strong>Hotel</strong><small>Standard hotel included</small></span><b>'+money(0)+'</b></div>')+(message?'<div class="booking-confirm-row '+(message.type==='success'?'discount':'coupon-warning')+'"><span>'+message.html+'</span><b>'+message.amount+'</b></div>':'')+'<div class="booking-confirm-total"><span>Total package amount</span><strong>'+money(details.total)+'</strong></div>';confirmModal.hidden=false;document.body.classList.add('booking-modal-open');confirmSubmit.focus()};
 const closeConfirmModal=()=>{confirmModal.hidden=true;document.body.classList.remove('booking-modal-open')};
 const updateHotelUpgrade=()=>{const option=hotelSelect?.selectedOptions[0],rate=Number(option?.dataset.surcharge||0),total=rate*Number(people.value||0);if(hotelUpgradeTotal)hotelUpgradeTotal.textContent=rate>0?'Hotel upgrade: '+new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(rate)+' per traveller · '+new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(total)+' total':'Standard hotel is included in the package price.'};
 const renumber=()=>list.querySelectorAll('.other-traveller-card').forEach((card,index)=>{card.querySelector('.traveller-number').textContent=index+1;card.querySelector('[name^="other_pwd["]').name='other_pwd['+index+']';card.querySelector('[name^="other_pwd_details["]').name='other_pwd_details['+index+']'});
 const updateCounts=()=>{const counts={total:0,child:0,adult:0,senior:0,pwd:0,female:0};if(includeSelf?.checked){counts.total++;const type=category(ageFromDob(includeSelf.dataset.dob));if(counts[type]!==undefined)counts[type]++;if(includeSelf.dataset.pwd==='1')counts.pwd++;if(includeSelf.dataset.gender==='Female')counts.female++}if(!familySection.hidden)document.querySelectorAll('input[name="family_ids[]"]:checked').forEach(input=>{counts.total++;const type=category(ageFromDob(input.dataset.dob));if(counts[type]!==undefined)counts[type]++;if(input.dataset.pwd==='1')counts.pwd++;if(input.dataset.gender==='Female')counts.female++});if(!otherSection.hidden)list.querySelectorAll('.other-traveller-card').forEach(card=>{counts.total++;const type=category(ageFromDob(card.querySelector('[name="other_dob[]"]').value));if(counts[type]!==undefined)counts[type]++;if(card.querySelector('[name^="other_pwd["]').checked)counts.pwd++;if(card.querySelector('[name="other_gender[]"]').value==='Female')counts.female++});Object.keys(counts).forEach(key=>{const output=document.querySelector('#count-'+key);if(output)output.textContent=counts[key]});people.value=counts.total;updateHotelUpgrade();updateOfferPreview()};
 const updateCardAge=input=>{const age=ageFromDob(input.value),output=input.parentElement.querySelector('.traveller-age');output.textContent=age===null?'':'Age '+age+' · '+category(age)[0].toUpperCase()+category(age).slice(1);updateCounts()};
 const addTraveller=()=>{const fragment=template.content.cloneNode(true),card=fragment.querySelector('.other-traveller-card');card.querySelector('.remove-traveller').addEventListener('click',()=>{card.remove();renumber();updateCounts()});card.querySelector('[name="other_dob[]"]').addEventListener('change',event=>updateCardAge(event.target));card.querySelector('[name="other_gender[]"]').addEventListener('change',updateCounts);card.querySelector('[name^="other_pwd["]').addEventListener('change',updateCounts);list.appendChild(fragment);renumber();updateCounts()};
 const setMode=()=>{const mode=document.querySelector('input[name="trip_category"]:checked').value,showFamily=mode==='family'||mode==='mixed',showOther=mode==='other'||mode==='mixed';familySection.hidden=!showFamily;otherSection.hidden=!showOther;familySection.querySelectorAll('input[type="checkbox"]').forEach(input=>input.disabled=!showFamily);list.querySelectorAll('input,select,textarea').forEach(input=>input.disabled=!showOther);if(showOther&&!list.children.length)addTraveller();updateCounts()};
 const conflictResult=document.querySelector('#date-conflict-result'),overlapConfirm=document.querySelector('#pending-overlap-confirm');let conflictTimer;
 const checkConflicts=()=>{clearTimeout(conflictTimer);if(!from.value||!to.value)return;conflictTimer=setTimeout(async()=>{conflictResult.hidden=false;conflictResult.className='date-conflict-result is-checking';conflictResult.textContent='Checking traveller availability...';overlapConfirm.hidden=true;overlapConfirm.querySelector('input').checked=false;try{const response=await fetch('booking-conflicts.php',{method:'POST',body:new FormData(document.querySelector('#booking-form')),headers:{'X-Requested-With':'XMLHttpRequest'}});const data=await response.json();if(!response.ok)throw new Error(data.error||'Check failed');const conflicts=data.conflicts||[];if(!conflicts.length){conflictResult.className='date-conflict-result is-clear';conflictResult.innerHTML='<i class="fa-solid fa-circle-check"></i><span>No overlapping trip was found for the selected travellers.</span>';return}const hard=conflicts.some(item=>item.severity==='hard');conflictResult.className='date-conflict-result '+(hard?'is-hard':'is-warning');conflictResult.innerHTML='<i class="fa-solid '+(hard?'fa-circle-xmark':'fa-triangle-exclamation')+'"></i><div><strong>'+(hard?'Dates unavailable':'Possible duplicate request')+'</strong>'+conflicts.map(item=>'<p>'+item.booking_reference+' · '+item.destination+' · '+item.from_date+' to '+item.to_date+' · '+item.status.replaceAll('_',' ')+'<br><small>Traveller(s): '+item.travellers.join(', ')+'</small></p>').join('')+'</div>';overlapConfirm.hidden=hard;}catch(error){conflictResult.className='date-conflict-result is-warning';conflictResult.textContent='Live availability could not be checked. It will be verified when you submit.'}},300)};
 const updateEndDate=()=>{to.min=from.value||'<?php echo date('Y-m-d');?>';if(!from.value){to.value='';conflictResult.hidden=true;return}const startDate=new Date(from.value+'T00:00:00');startDate.setDate(startDate.getDate()+durationDays-1);to.value=[startDate.getFullYear(),String(startDate.getMonth()+1).padStart(2,'0'),String(startDate.getDate()).padStart(2,'0')].join('-');checkConflicts()};
 document.querySelectorAll('input[name="trip_category"]').forEach(input=>input.addEventListener('change',()=>{setMode();checkConflicts()}));document.querySelectorAll('input[name="family_ids[]"]').forEach(input=>input.addEventListener('change',()=>{updateCounts();checkConflicts()}));includeSelf?.addEventListener('change',()=>{updateCounts();checkConflicts()});addButton.addEventListener('click',addTraveller);from.addEventListener('change',updateEndDate);hotelSelect?.addEventListener('change',()=>{updateHotelUpgrade();updateOfferPreview()});offerInput?.addEventListener('input',updateOfferPreview);list.addEventListener('change',event=>{if(event.target.matches('[name="other_name[]"],[name="other_dob[]"]'))checkConflicts()});
 if(editBookingData){from.value=editBookingData.from_date;hotelSelect.value=String(editBookingData.hotel_id);includeSelf.checked=editBookingData.include_self;document.querySelectorAll('input[name="trip_category"]').forEach(input=>input.checked=input.value===editBookingData.trip_category);document.querySelectorAll('input[name="family_ids[]"]').forEach(input=>input.checked=editBookingData.family_ids.includes(Number(input.value)));document.querySelector('[name="offer_code"]').value=editBookingData.offer_code;document.querySelector('[name="customer_note"]').value=editBookingData.customer_note;document.querySelector('.submit-row button').innerHTML='<i class="fa-solid fa-paper-plane"></i> Send updated request'}
 setMode();
 if(editBookingData){editBookingData.other_travellers.forEach((traveller,index)=>{if(index>0||!list.children.length)addTraveller();const card=list.children[index];card.querySelector('[name="other_name[]"]').value=traveller.name;card.querySelector('[name="other_relationship[]"]').value=traveller.relationship||'';card.querySelector('[name="other_dob[]"]').value=traveller.date_of_birth;card.querySelector('[name="other_gender[]"]').value=traveller.gender||'';card.querySelector('[name="other_phone[]"]').value=traveller.phone||'';card.querySelector('[name="other_medical[]"]').value=traveller.medical_issues||'';card.querySelector('[name^="other_pwd["]').checked=traveller.is_pwd===1;card.querySelector('[name^="other_pwd_details["]').value=traveller.pwd_details||'';updateCardAge(card.querySelector('[name="other_dob[]"]'))})}
 updateEndDate();updateCounts();
 document.querySelectorAll('[data-close-booking-confirm]').forEach(button=>button.addEventListener('click',closeConfirmModal));
 document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!confirmModal.hidden)closeConfirmModal()});
 confirmSubmit.addEventListener('click',()=>{bookingConfirmed=true;closeConfirmModal();bookingForm.requestSubmit()});
 bookingForm.addEventListener('submit',event=>{updateCounts();if(Number(people.value)<1){event.preventDefault();alert('Select or add at least one traveller.');return}if(!bookingConfirmed){event.preventDefault();openConfirmModal()}});
});
</script></body></html>
